package cms

import (
	"testing"

	"github.com/gmrtd/gmrtd/utils"
)

// real CMS SignedData (EC-signed SOD payload), reused from TestSelectCertificateBasic
var fuzzSignedDataBytes = utils.HexToBytes("")

// real RSASSA-PSS-signed SOD SignedData (MY), reused from TestVerifySignedData
var fuzzSignedDataRsaPssBytes = utils.HexToBytes("")

// real sha256WithRSAEncryption-signed SOD SignedData (FR), reused from TestVerifySignedData
var fuzzSignedDataRsaBytes = utils.HexToBytes("")

// real RSASSA-PSS-signed CSCA link certificate (SG "Singapore Passport CA 5")
var fuzzCertBytes = utils.HexToBytes("")

// minimal valid DER RDNSequence: {countryName=US}
var fuzzRdnBytes = utils.HexToBytes("300D310B3009060355040613025553")

// P-384 EC SubjectPublicKeyInfo, reused from TestEcCurveWithConfigValidCurve
var fuzzEcSpkiBytes = utils.HexToBytes("3076301006072a8648ce3d020106052b81040020036200048aca5f821170fa4d8233c7f23f795792af42e791045bdf55989684aa16d1027d27541b0226d665c50e0ff76f91f5aeebf6af5178c02204045aa43002c893ed2b800cafa1e42cb47f80a21a6f0c3a2919bc5242c21daca5f4ec3c270e5620eb7c")

// RSA SubjectPublicKeyInfo, reused from TestEcCurveWithConfigNonECKey
var fuzzRsaSpkiBytes = utils.HexToBytes("")

func FuzzParseSignedData(f *testing.F) {
	f.Add([]byte(nil))
	f.Add([]byte{0xff, 0x00})
	f.Add(fuzzSignedDataBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = ParseSignedData(data)
	})
}

func FuzzParseCertificates(f *testing.F) {
	f.Add([]byte(nil))
	f.Add([]byte{0xDE, 0xAD, 0xBE, 0xEF})
	f.Add(fuzzCertBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = ParseCertificates(data)
	})
}

func FuzzParseRDNSequence(f *testing.F) {
	f.Add([]byte(nil))
	f.Add([]byte{0xDE, 0xAD, 0xBE, 0xEF})
	f.Add(fuzzRdnBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = ParseRDNSequence(data)
	})
}

func FuzzAsn1decodeSubjectPublicKeyInfo(f *testing.F) {
	f.Add([]byte(nil))
	f.Add(fuzzEcSpkiBytes)
	f.Add(fuzzRsaSpkiBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = Asn1decodeSubjectPublicKeyInfo(data)
	})
}

func FuzzCertificateInfo(f *testing.F) {
	f.Add([]byte(nil))
	f.Add([]byte{0xDE, 0xAD, 0xBE, 0xEF})
	f.Add(fuzzCertBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		certs, err := ParseCertificates(data)
		if err != nil {
			return
		}
		for i := range certs {
			_ = certs[i].Info()
			_ = certs[i].IsLinkCert()
		}
	})
}

// fuzzMasterList loads the default CSCA pool once per process, as each fuzz worker would
// otherwise re-parse and re-verify every embedded master list on every input.
func fuzzMasterList(f *testing.F) CertPool {
	f.Helper()
	pool, err := DefaultMasterList()
	if err != nil {
		f.Fatalf("DefaultMasterList error: %s", err)
	}
	return pool
}

// The seeds verify against the default CSCA pool, so mutations reach the signed-attribute,
// digest, signature and certificate-chain checks rather than stopping at the parser. The
// signer certificate and signature come from the chip, so all of this is attacker-controlled.
func FuzzSignedDataVerify(f *testing.F) {
	pool := fuzzMasterList(f)

	f.Add(fuzzSignedDataBytes)
	f.Add(fuzzSignedDataRsaPssBytes)
	f.Add(fuzzSignedDataRsaBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		sd, err := ParseSignedData(data)
		if err != nil {
			return
		}
		certChain, err := sd.Verify(pool)
		if err == nil && len(certChain) == 0 {
			t.Fatalf("Verify succeeded with an empty certificate chain")
		}
	})
}

func FuzzCertificateVerify(f *testing.F) {
	pool := fuzzMasterList(f)

	f.Add(fuzzCertBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		certs, err := ParseCertificates(data)
		if err != nil {
			return
		}
		for i := range certs {
			_, _ = certs[i].Verify(pool)
		}
	})
}
